import { products } from './data.js';
// Data stays immutable; edits are isolated to this page session.
const records = products.map(p => ({ ...p }));
const permissions = new Map(products.map(p => [p.id, p.canEdit]));
const app = document.querySelector('#app');
const dialog = document.querySelector('#record-dialog');
const esc = value => String(value).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('en-US', {style:'currency',currency:'USD'}).format(value);
let state = ['empty','loading','error'].includes(new URLSearchParams(location.search).get('state')) ? new URLSearchParams(location.search).get('state') : 'populated';
let filters = { search:'', category:'', status:'', stock:'' };
let view = 'auto';
let currentId = null, editing = false, returnTarget = null, toastTimer;
const announce = text => { document.querySelector('#announcement').textContent = text; };
const notify = text => { const toast=document.querySelector('#toast');toast.textContent=text;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,6000); };
const getRecord = id => records.find(p=>p.id===id);
const canEdit = id => permissions.get(id) === true;
function renderShell() {
 app.innerHTML = "'`<section class="intro"><div><p class="eyebrow">Operations / Catalog</p><h1>Inventory</h1><p>Keep every part in view. Keep work moving.</p></div><p class="session-note">Workspace changes are saved<br>for this page session.</p></section><section class="metrics" aria-label="Inventory overview"></section><section class="workspace" aria-label="Product inventory"><div class="filters"><label class="search-label">Search products<input type="search" data-testid="search" placeholder="Search by name or SKU" autocomplete="off"></label><label>Category<select id="category"><option value="">All categories</option>${['"'Hardware','Inspection','Storage'].map(s=>"'`<option>${s}</option>`).join('"'')}</select></label><label>Lifecycle status<select id=\"status\"><option value=\"\">All statuses</option>"'${['"'Active','Draft','Archived'].map(s=>"'`<option>${s}</option>`).join('"'')}</select></label><label class=\"stock-filter\">Stock availability<select id=\"stock\"><option value=\"\">Any stock level</option><option value=\"in\">In stock (1+)</option><option value=\"low\">Low stock (1–10)</option><option value=\"out\">Out of stock (0)</option></select></label></div><div class=\"result-bar\"><h2 id=\"results-title\" tabindex=\"-1\"></h2><div class=\"view-switch\" aria-label=\"Product layout\"><button data-view=\"table\">Table</button><button data-view=\"cards\">Cards</button></div></div><div class=\"chips\" aria-label=\"Active filters\"></div><div id=\"results\"></div><footer class=\"table-footer\"><span>Prices in USD · Stock in units</span><span>Select a product for full details & permissions</span></footer></section>"'`;
 app.querySelector('"'[data-testid=\"search\"]').addEventListener('input',e=>{filters.search=e.target.value;renderResults();});
 ['category','status','stock'].forEach(key=>app.querySelector('#'+key).addEventListener('change',e=>{filters[key]=e.target.value;renderResults();}));
 renderResults();
}
function selectedView(){ return view==='auto' ? (matchMedia('(max-width:760px)').matches?'cards':'table') : view; }
function renderMetrics(){ const source=state==='populated'?records:[];app.querySelector('.metrics').innerHTML="'`<div class="metric"><span>Total products</span><strong>${state==='"'loading'?'—':source.length}</strong></div><div class=\"metric\"><span>Active products</span><strong>"'${state==='"'loading'?'—':source.filter(p=>p.status==='Active').length}</strong></div><div class=\"metric zero\"><span>Out of stock</span><strong>"'${state==='"'loading'?'—':source.filter(p=>p.stock===0).length}</strong></div>"'`; }
function matching(){return records.filter(p=>(!filters.search||`${p.name} ${p.sku}`.toLowerCase().includes(filters.search.trim().toLowerCase()))&&(!filters.category||p.category===filters.category)&&(!filters.status||p.status===filters.status)&&(!filters.stock||(filters.stock==='"'out'?p.stock===0:filters.stock==='low'?p.stock>0&&p.stock<=10:p.stock>0)));}
function renderResults(){
 renderMetrics();
 const list=state==='populated'?matching():[];
